using Microsoft.Extensions.Logging;

namespace Pragmatic.Logging.Benchmarks.Modules;

/// <summary>
///     The same two methods of the cache stack as Pragmatic.Caching declares them today: generated by
///     Microsoft, written fully qualified for that reason. Instance methods finding the logger in a
///     <c>_logger</c> field, as the stack's do.
/// </summary>
internal sealed partial class CachingMicrosoftLog(ILogger logger)
{
    private readonly ILogger _logger = logger;

    [Microsoft.Extensions.Logging.LoggerMessage(Level = LogLevel.Debug, Message = CachingCallSiteLog.GetOrSetTemplate)]
    public partial void LogGetOrSet(string key);

    [Microsoft.Extensions.Logging.LoggerMessage(Level = LogLevel.Warning, Message = CachingCallSiteLog.TagInvalidationFailedTemplate)]
    public partial void LogTagInvalidationFailed(string tag, Exception exception);
}
